# characters (Nura, Salem, Maryam…) are fictional.

P = lambda en, ar: {'en': en, 'ar': ar}

# ---------------------------------------------------------------- art helpers
def A(bg='day', ground='sand', horizon=170, sun=None, back=None, el=None, people=None, front=None, bubble=None):
    d = {'bg': bg, 'ground': ground, 'horizon': horizon}
    if sun: d['sun'] = sun
    if back: d['back'] = back
    if el: d['el'] = el
    if people: d['people'] = people
    if front: d['front'] = front
    if bubble: d['bubble'] = bubble
    return d

def M(t, x, y, s=1, flip=False):
    m = {'t': t, 'x': x, 'y': y, 's': s}
    if flip: m['flip'] = True
    return m

def H(t, x, y, pose='stand', s=1, flip=False, hat=None, back=False, step=0):
    p = {'t': t, 'x': x, 'y': y, 's': s, 'pose': pose, 'flip': flip, 'back': back, 'hat': hat, 'step': step}
    return p

LAB = A('wall', 'floor', 180, el=[M('lab', 150, 230, 1.1), M('map', 360, 225, 0.9)])

